-- TidehookLagoonHooks (ModuleScript, generated by hooks_lua.py from anchors.json). Run AFTER TidehookLagoonSetup.Build().
-- Makes workspace.TidehookLagoon.Hooks: invisible, anchored, non-colliding anchor Parts the game scripts bind to:
--   kind station   : station name GUI spot (BillboardGui goes here; nothing is written in the meshes)
--   kind sell      : sell counter trigger box (ProximityPrompt / Touched)
--   kind fishing   : cast spot on a pier end (railing gap) - player stands here and casts outward (LookVector)
--   kind fishzone  : water area to cast into (deep water by the marker buoys, lagoon beginner spots)
--   kind boat      : boat spawn (waterline, LookVector = bow)
--   kind spawn     : SpawnLocation (created as a real SpawnLocation, invisible)
-- Row = {name, kind, x, y, z, yaw (deg, LookVector = -Z turned by yaw), size x, y, z}. Idempotent (replaces Hooks).
local M = {}
M.Rows = {
	{"QuestBoard", "station", -15.5, 15.5, 85.5, 270, 4, 1, 4},
	{"SpawnLocation", "spawn", 0, 5, 87.5, 0, 12, 1, 12},
	{"RodShop", "station", -59.04, 27.5, 59.04, 315, 4, 1, 4},
	{"BaitShop", "station", 58.69, 29.5, 58.69, 45, 4, 1, 4},
	{"FishMarket", "station", 83.5, 28.5, 0, 90, 4, 1, 4},
	{"SellCounter", "sell", 75.5, 7.5, 0, 90, 19, 4, 3},
	{"BoatDock", "station", -80.5, 30.5, -7, 270, 4, 1, 4},
	{"BoatSpawn1", "boat", -108, 1, -8, 90, 5, 2, 12},
	{"BoatSpawn2", "boat", -108, 1, 8, 90, 5, 2, 12},
	{"Aquarium", "station", 0, 34.5, 24, 180, 4, 1, 4},
	{"FishIndex", "station", -17.73, 18, 19.69, 138, 4, 1, 4},
	{"PierNE_Spot1", "fishing", 90.51, 5, -90.51, 135, 6, 1, 3},
	{"PierNE_Spot2", "fishing", 92.28, 5, -79.55, 135, 6, 1, 3},
	{"PierNE_Spot3", "fishing", 79.55, 5, -92.28, 135, 6, 1, 3},
	{"PierNE_Deep1", "fishzone", 111.72, 0, -91.92, 0, 24, 1, 24},
	{"PierNE_Deep2", "fishzone", 96.17, 0, -118.79, 0, 24, 1, 24},
	{"PierN_Spot1", "fishing", 8.25, 5, -150, 180, 6, 1, 3},
	{"PierN_Spot2", "fishing", -8.25, 5, -150, 180, 6, 1, 3},
	{"PierN_Spot3", "fishing", 15, 5, -144, 180, 6, 1, 3},
	{"PierN_Spot4", "fishing", -15, 5, -144, 180, 6, 1, 3},
	{"PierN_Deep1", "fishzone", 14, 0, -166, 0, 24, 1, 24},
	{"PierN_Deep2", "fishzone", -16, 0, -174, 0, 24, 1, 24},
	{"PierNW_Spot1", "fishing", -87.68, 5, -87.68, 225, 6, 1, 3},
	{"PierNW_Spot2", "fishing", -76.72, 5, -89.45, 225, 6, 1, 3},
	{"PierNW_Spot3", "fishing", -89.45, 5, -76.72, 225, 6, 1, 3},
	{"PierNW_Deep1", "fishzone", -89.1, 0, -108.89, 0, 24, 1, 24},
	{"PierNW_Deep2", "fishzone", -115.97, 0, -93.34, 0, 24, 1, 24},
	{"Lagoon_0", "fishzone", 12, 0, 45, 0, 14, 1, 14},
	{"Lagoon_90", "fishzone", 45, 0, 12, 0, 14, 1, 14},
	{"Lagoon_180", "fishzone", -12, 0, -45, 0, 14, 1, 14},
}
function M.Build(root)
	root = root or workspace:FindFirstChild("TidehookLagoon") or workspace
	local old = root:FindFirstChild("Hooks"); if old then old:Destroy() end
	local f = Instance.new("Folder"); f.Name = "Hooks"
	for _, r in M.Rows do
		local cf = CFrame.new(r[3], r[4], r[5]) * CFrame.Angles(0, math.rad(r[6]), 0)
		local p = r[2] == "spawn" and Instance.new("SpawnLocation") or Instance.new("Part")
		p.Name = r[1]; p.Anchored = true; p.CanCollide = false; p.CanQuery = r[2] ~= "station"; p.CanTouch = r[2] ~= "station"
		p.Transparency = 1; p.Size = Vector3.new(r[7], r[8], r[9]); p.CFrame = cf
		p:SetAttribute("HookKind", r[2])
		if r[2] == "spawn" then p.Neutral = true; p.Duration = 0 end
		if r[2] == "station" then                              -- default label (replace with the game's own GUI style)
			local g = Instance.new("BillboardGui"); g.Name = "Label"; g.Size = UDim2.fromOffset(240, 60)
			g.AlwaysOnTop = false; g.MaxDistance = 220; g.LightInfluence = 0
			local t = Instance.new("TextLabel"); t.Size = UDim2.fromScale(1, 1); t.BackgroundTransparency = 1
			t.Text = r[1]:gsub("(%l)(%u)", "%1 %2"); t.TextScaled = true; t.Font = Enum.Font.FredokaOne
			t.TextColor3 = Color3.new(1, 1, 1); t.TextStrokeTransparency = 0; t.Parent = g; g.Parent = p
		end
		local folder = f:FindFirstChild(r[2]) or Instance.new("Folder", f); folder.Name = r[2]
		p.Parent = folder
	end
	f.Parent = root
	return f
end
return M
